rows=[]
for p in sorted((w/'student').glob('*.md')):
 for part in re.split(r'(?m)(?=^## task: )',p.read_text())[1:]:
  ident=part.split(' |')[0].split('## task: ')[1];cond=part.split('### Заготовка')[0].split('Доступные строки')[0].strip()
